let PERSON_FULL_NAME="NOEL TAYLOR",experienceData=[{title:"SENIOR WEB DESIGNER",period:"2020 -Present",company:"Creative Agency / Chicago",text:"Lorem Ipsum has been the industry's standard dummy text ever since 1500s, when unknown printer took a galley of type."},{title:"GRAPHIC DESIGNER",period:"2015 -2020",company:"Creative Market / Chicago",text:"Lorem Ipsum has been the industry's standard dummy text ever since 1500s, when unknown printer took a galley of type."},{title:"MARKETING MANAGER",period:"2013 -2015",company:"Manufacturing Agency / NJ",text:"Lorem Ipsum has been the industry's standard dummy text ever since 1500s, when unknown printer took a galley of type."}],skillsData=[{name:"Adobe Photoshop",level:80},{name:"Adobe Illustrator",level:75},{name:"Microsoft Word",level:90},{name:"Microsoft Powerpoint",level:85},{name:"HTML-5/CSS-3",level:70}];function setPersonName(e,t){e=document.getElementById(e);e&&(e.textContent=t)}function renderExperience(e,t){e=document.getElementById(e);e&&(e.innerHTML="",t=t.map(({title:e,period:t,company:n,text:i})=>`
      <article class="job-item">
        <div class="d-flex justify-content-between align-items-center">
          <h3>${e}</h3>
          <span class="job-item__period">${t}</span>
        </div>
        <p class="job-item__company">${n}</p>
        <p class="job-item__text">${i}</p>
      </article>`).join(""),e.insertAdjacentHTML("beforeend",t))}function renderSkills(e,t){e=document.getElementById(e);e&&(e.innerHTML="",t=t.map(({name:e,level:t})=>`
      <div class="skill-item col-6 d-flex align-items-center">
        <span class="skill-name">${e}</span>
        <div class="skill-track"><div class="skill-bar-fill skill-${t}"></div></div>
      </div>`).join(""),e.insertAdjacentHTML("beforeend",t))}function toggleSection(e){var t=document.getElementById(e.dataset.target);t&&(t=t.classList.toggle("is-hidden"),e.classList.toggle("is-flipped",t),e.setAttribute("aria-expanded",String(!t)))}function initToggles(){document.querySelectorAll(".toggle-arrow").forEach(e=>{e.addEventListener("click",()=>toggleSection(e))})}document.addEventListener("DOMContentLoaded",()=>{setPersonName("personName",PERSON_FULL_NAME),renderExperience("experience-list",experienceData),renderSkills("skills-list",skillsData),initToggles()});